-- Step 7.2D.0.1 - Compatibilità alimentare del catalogo base.
--
-- Questa migration NON modifica né ricrea il catalogo alimenti introdotto da
-- 20260825014500_catalogo_alimenti_base.sql.
--
-- Le etichette descrivono diete/esclusioni deducibili dagli ingredienti:
-- vegano, vegetariano, pescetariano e principali esclusioni/allergeni.
--
-- Stato:
--   si         = compatibile sulla base dell'alimento generico;
--   no         = incompatibilità nota;
--   verificare = formulazione/marca/processo possono cambiare il risultato.
--
-- Le compatibilità sono un supporto gestionale, non una certificazione
-- sanitaria: per allergie/intolleranze reali resta necessario verificare
-- etichetta, contaminazioni e specifica formulazione del prodotto.

CREATE TABLE etichette_alimentari (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    codice TEXT NOT NULL UNIQUE,
    nome TEXT NOT NULL UNIQUE,
    emoji TEXT NOT NULL,
    tipo TEXT NOT NULL CHECK (tipo IN ('dieta', 'esclusione')),
    ordinamento INTEGER NOT NULL DEFAULT 0,
    attiva INTEGER NOT NULL DEFAULT 1 CHECK (attiva IN (0, 1))
);

CREATE TABLE alimento_compatibilita (
    alimento_id INTEGER NOT NULL
        REFERENCES alimenti(id) ON DELETE CASCADE,
    etichetta_id INTEGER NOT NULL
        REFERENCES etichette_alimentari(id) ON DELETE CASCADE,
    stato TEXT NOT NULL CHECK (stato IN ('si', 'no', 'verificare')),
    fonte TEXT NOT NULL DEFAULT 'manuale',
    nota TEXT,
    aggiornato_il TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (alimento_id, etichetta_id)
);

CREATE INDEX idx_alimento_compatibilita_etichetta_stato
ON alimento_compatibilita(etichetta_id, stato, alimento_id);

