INSERT INTO alimento_compatibilita (
    alimento_id,
    etichetta_id,
    stato,
    fonte
)
SELECT
    a.id,
    e.id,
    compat.stato,
    'catalogo_base_2026_08'
FROM compat
JOIN alimenti a
  ON a.nome_normalizzato = compat.nome_normalizzato
 AND a.catalogo_globale = 1
 AND a.archiviato = 0
JOIN etichette_alimentari e
  ON e.codice = compat.etichetta_codice;

CREATE VIEW v_ricetta_compatibilita_alimentare AS
SELECT
    r.id AS ricetta_id,
    e.id AS etichetta_id,
    e.codice AS etichetta_codice,
    e.nome AS etichetta_nome,
    e.emoji AS etichetta_emoji,
    e.tipo AS etichetta_tipo,
    e.ordinamento AS ordinamento,
    CASE
        WHEN SUM(CASE WHEN ac.stato = 'no' THEN 1 ELSE 0 END) > 0
            THEN 'no'
        WHEN SUM(
            CASE
                WHEN ac.stato = 'verificare' OR ac.stato IS NULL THEN 1
                ELSE 0
            END
        ) > 0
            THEN 'verificare'
        ELSE 'si'
    END AS stato,
    COUNT(ri.alimento_id) AS ingredienti_totali,
    SUM(CASE WHEN ac.stato = 'no' THEN 1 ELSE 0 END)
        AS ingredienti_non_compatibili,
    SUM(
        CASE
            WHEN ac.stato = 'verificare' OR ac.stato IS NULL THEN 1
            ELSE 0
        END
    ) AS ingredienti_da_verificare
FROM ricette r
JOIN ricetta_ingredienti ri
  ON ri.ricetta_id = r.id
CROSS JOIN etichette_alimentari e
LEFT JOIN alimento_compatibilita ac
  ON ac.alimento_id = ri.alimento_id
 AND ac.etichetta_id = e.id
WHERE r.archiviata = 0
  AND e.attiva = 1
GROUP BY
    r.id,
    e.id,
    e.codice,
    e.nome,
    e.emoji,
    e.tipo,
    e.ordinamento;
